import { render, screen, mockArticle } from '../utils/test-utils'
import { ArticleCard, ArticleCardSkeleton } from '@/components/blog/ArticleCard'

// Mock next/link
jest.mock('next/link', () => {
  const MockLink = ({ children, href }) => <a href={href}>{children}</a>
  MockLink.displayName = 'MockLink'
  return MockLink
})

describe('ArticleCard', () => {
  describe('English locale', () => {
    it('renders article title in English', () => {
      render(<ArticleCard article={mockArticle} locale="en" />)
      expect(screen.getByText('Test Article Title')).toBeInTheDocument()
    })

    it('renders article excerpt in English', () => {
      render(<ArticleCard article={mockArticle} locale="en" />)
      expect(screen.getByText('This is a test excerpt for the article.')).toBeInTheDocument()
    })

    it('renders category name in English', () => {
      render(<ArticleCard article={mockArticle} locale="en" />)
      expect(screen.getByText('Technology')).toBeInTheDocument()
    })

    it('renders reading time', () => {
      render(<ArticleCard article={mockArticle} locale="en" />)
      expect(screen.getByText('5 min read')).toBeInTheDocument()
    })

    it('renders Read more link with correct URL', () => {
      render(<ArticleCard article={mockArticle} locale="en" />)
      const readMoreLink = screen.getByText('Read more')
      expect(readMoreLink.closest('a')).toHaveAttribute('href', '/en/blog/test-article')
    })

    it('renders tags', () => {
      render(<ArticleCard article={mockArticle} locale="en" />)
      expect(screen.getByText('#React')).toBeInTheDocument()
      expect(screen.getByText('#Next.js')).toBeInTheDocument()
    })

    it('renders view count when > 0', () => {
      render(<ArticleCard article={mockArticle} locale="en" />)
      expect(screen.getByText('100')).toBeInTheDocument()
    })

    it('has ltr direction', () => {
      render(<ArticleCard article={mockArticle} locale="en" />)
      const article = screen.getByRole('article')
      expect(article).toHaveAttribute('dir', 'ltr')
    })
  })

  describe('Persian locale', () => {
    it('renders article title in Persian', () => {
      render(<ArticleCard article={mockArticle} locale="fa" />)
      expect(screen.getByText('عنوان آزمایشی مقاله')).toBeInTheDocument()
    })

    it('renders article excerpt in Persian', () => {
      render(<ArticleCard article={mockArticle} locale="fa" />)
      expect(screen.getByText('این یک خلاصه آزمایشی برای مقاله است.')).toBeInTheDocument()
    })

    it('renders category name in Persian', () => {
      render(<ArticleCard article={mockArticle} locale="fa" />)
      expect(screen.getByText('فناوری')).toBeInTheDocument()
    })

    it('renders reading time in Persian', () => {
      render(<ArticleCard article={mockArticle} locale="fa" />)
      expect(screen.getByText('5 دقیقه')).toBeInTheDocument()
    })

    it('renders ادامه مطلب link with correct URL', () => {
      render(<ArticleCard article={mockArticle} locale="fa" />)
      const readMoreLink = screen.getByText('ادامه مطلب')
      expect(readMoreLink.closest('a')).toHaveAttribute('href', '/fa/blog/test-article')
    })

    it('has rtl direction', () => {
      render(<ArticleCard article={mockArticle} locale="fa" />)
      const article = screen.getByRole('article')
      expect(article).toHaveAttribute('dir', 'rtl')
    })
  })

  describe('Featured article', () => {
    it('shows featured badge when article is featured', () => {
      const featuredArticle = { ...mockArticle, is_featured: true }
      render(<ArticleCard article={featuredArticle} locale="en" />)
      expect(screen.getByText('⭐ Featured')).toBeInTheDocument()
    })

    it('shows Persian featured badge in fa locale', () => {
      const featuredArticle = { ...mockArticle, is_featured: true }
      render(<ArticleCard article={featuredArticle} locale="fa" />)
      expect(screen.getByText('⭐ ویژه')).toBeInTheDocument()
    })
  })

  describe('Missing data handling', () => {
    it('renders without featured image', () => {
      const articleWithoutImage = { ...mockArticle, featured_image: null }
      render(<ArticleCard article={articleWithoutImage} locale="en" />)
      expect(screen.getByText('📝')).toBeInTheDocument()
    })

    it('renders without category', () => {
      const articleWithoutCategory = { ...mockArticle, category: null }
      render(<ArticleCard article={articleWithoutCategory} locale="en" />)
      expect(screen.getByText('Test Article Title')).toBeInTheDocument()
    })

    it('renders without tags', () => {
      const articleWithoutTags = { ...mockArticle, tags: [] }
      render(<ArticleCard article={articleWithoutTags} locale="en" />)
      expect(screen.getByText('Test Article Title')).toBeInTheDocument()
    })

    it('does not show view count when 0', () => {
      const articleNoViews = { ...mockArticle, view_count: 0 }
      render(<ArticleCard article={articleNoViews} locale="en" />)
      expect(screen.queryByText('0')).not.toBeInTheDocument()
    })
  })

  describe('Truncated tags', () => {
    it('shows +N when more than 3 tags', () => {
      const articleWithManyTags = {
        ...mockArticle,
        tags: [
          { id: '1', slug: 'tag1', name_en: 'Tag1', name_fa: 'تگ۱' },
          { id: '2', slug: 'tag2', name_en: 'Tag2', name_fa: 'تگ۲' },
          { id: '3', slug: 'tag3', name_en: 'Tag3', name_fa: 'تگ۳' },
          { id: '4', slug: 'tag4', name_en: 'Tag4', name_fa: 'تگ۴' },
          { id: '5', slug: 'tag5', name_en: 'Tag5', name_fa: 'تگ۵' },
        ],
      }
      render(<ArticleCard article={articleWithManyTags} locale="en" />)
      expect(screen.getByText('+2')).toBeInTheDocument()
    })
  })
})

describe('ArticleCardSkeleton', () => {
  it('renders skeleton placeholder', () => {
    const { container } = render(<ArticleCardSkeleton />)
    expect(container.querySelector('.animate-pulse')).toBeInTheDocument()
  })
})

'use client'

import { useState, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import Link from 'next/link'
import { ArticleCard } from '@/components/blog/ArticleCard'
import { getHomepageArticles } from '@/lib/actions/articles'

export const ArticlesSection = () => {
  const { t, i18n } = useTranslation()
  const [isExpanded, setIsExpanded] = useState(false)
  const [articles, setArticles] = useState([])
  const [loading, setLoading] = useState(true)

  const locale = i18n.language || 'en'
  const isRtl = locale === 'fa'

  // Display counts: 6 on desktop, 3 on mobile
  const articlesToDisplay = isExpanded ? articles : articles.slice(0, 6)

  // Fetch articles
  useEffect(() => {
    async function loadArticles() {
      setLoading(true)
      try {
        const { articles: articlesData } = await getHomepageArticles(12)
        setArticles(articlesData || [])
      } catch (error) {
        console.error('Failed to load articles:', error)
        setArticles([])
      } finally {
        setLoading(false)
      }
    }
    loadArticles()
  }, [])

  if (loading) {
    return (
      <section id="articles" className="py-24 px-4 relative">
        <div className="container mx-auto max-w-5xl">
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
          </div>
        </div>
      </section>
    )
  }

  // Don't render section if no articles
  if (articles.length === 0) {
    return null
  }

  return (
    <section id="articles" className="py-24 px-4 relative">
      <div className="container mx-auto max-w-5xl">
        {/* Section Header */}
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-4xl font-bold mb-4">
            {t('articles.title')} <span className="text-primary">{t('articles.articles')}</span>
          </h2>
          <p className="text-muted-foreground max-w-2xl mx-auto">
            {t('articles.description')}
          </p>
        </div>

        {/* Articles Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {articlesToDisplay.map((article) => (
            <ArticleCard key={article.id} article={article} locale={locale} />
          ))}
        </div>

        {/* Show More/Less Button */}
        {articles.length > 6 && (
          <div className="flex justify-center mt-8">
            <button
              onClick={() => setIsExpanded(!isExpanded)}
              className={`px-6 py-2 rounded-full bg-primary text-primary-foreground hover:opacity-90 transition-opacity ${isRtl ? 'font-persian' : ''}`}
            >
              {isExpanded ? t('common.showLess') : t('common.showMore')}
            </button>
          </div>
        )}

        {/* View All Link */}
        <div className="text-center mt-6">
          <Link
            href={`/${locale}/blog`}
            className={`inline-flex items-center gap-2 text-muted-foreground hover:text-primary transition-colors ${isRtl ? 'flex-row-reverse font-persian' : ''}`}
          >
            {isRtl ? 'مشاهده همه مقالات' : 'View all articles'}
            <svg className={`w-4 h-4 ${isRtl ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </Link>
        </div>
      </div>
    </section>
  )
}

'use client'

import Link from 'next/link'
import { ChevronRight } from 'lucide-react'

// Breadcrumbs component with JSON-LD schema markup
export function Breadcrumbs({ items, locale = 'en' }) {
  const isRtl = locale === 'fa'

  if (!items?.length) return null

  // Generate JSON-LD for breadcrumbs
  const breadcrumbJsonLd = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: item.label,
      ...(item.href && {
        item: `https://hasanshiri.online${item.href}`,
      }),
    })),
  }

  return (
    <>
      {/* JSON-LD Schema */}
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbJsonLd) }}
      />

      {/* Visual Breadcrumbs */}
      <nav
        aria-label="Breadcrumb"
        className={`mb-4 ${isRtl ? 'text-right' : 'text-left'}`}
        dir={isRtl ? 'rtl' : 'ltr'}
      >
        <ol
          className={`flex flex-wrap items-center gap-1 text-sm text-muted-foreground ${isRtl ? 'flex-row-reverse' : ''}`}
        >
          {items.map((item, index) => {
            const isLast = index === items.length - 1

            return (
              <li
                key={index}
                className={`flex items-center gap-1 ${isRtl ? 'flex-row-reverse' : ''}`}
              >
                {index > 0 && (
                  <ChevronRight
                    className={`w-4 h-4 text-muted-foreground/50 ${isRtl ? 'rotate-180' : ''}`}
                  />
                )}
                {isLast || !item.href ? (
                  <span
                    className={`${isLast ? 'text-foreground font-medium' : ''} truncate max-w-[200px]`}
                    aria-current={isLast ? 'page' : undefined}
                  >
                    {item.label}
                  </span>
                ) : (
                  <Link
                    href={item.href}
                    className="hover:text-foreground transition-colors truncate max-w-[200px]"
                  >
                    {item.label}
                  </Link>
                )}
              </li>
            )
          })}
        </ol>
      </nav>
    </>
  )
}

export default Breadcrumbs

import { render, screen, waitFor } from '../utils/test-utils'
import userEvent from '@testing-library/user-event'
import { CommentForm } from '@/components/comments/CommentForm'

// Mock the createComment action
jest.mock('@/lib/actions/comments', () => ({
  createComment: jest.fn(),
}))

import { createComment } from '@/lib/actions/comments'

describe('CommentForm', () => {
  const defaultProps = {
    articleId: '123',
    user: null,
    locale: 'en',
    parentId: null,
    onCommentAdded: jest.fn(),
    onCancel: null,
  }

  beforeEach(() => {
    jest.clearAllMocks()
  })

  describe('Guest mode (not logged in)', () => {
    it('renders name and email fields for guests', () => {
      render(<CommentForm {...defaultProps} />)

      expect(screen.getByPlaceholderText('Your name *')).toBeInTheDocument()
      expect(screen.getByPlaceholderText('Your email *')).toBeInTheDocument()
    })

    it('renders textarea for comment', () => {
      render(<CommentForm {...defaultProps} />)

      expect(screen.getByPlaceholderText('Share your thoughts...')).toBeInTheDocument()
    })

    it('renders Post Comment button', () => {
      render(<CommentForm {...defaultProps} />)

      expect(screen.getByRole('button', { name: /post comment/i })).toBeInTheDocument()
    })

    it('shows character count', () => {
      render(<CommentForm {...defaultProps} />)

      expect(screen.getByText('0/2000')).toBeInTheDocument()
    })

    it('updates character count when typing', async () => {
      const user = userEvent.setup()
      render(<CommentForm {...defaultProps} />)

      const textarea = screen.getByPlaceholderText('Share your thoughts...')
      await user.type(textarea, 'Hello')

      expect(screen.getByText('5/2000')).toBeInTheDocument()
    })

    it('shows privacy note for guests', () => {
      render(<CommentForm {...defaultProps} />)

      expect(
        screen.getByText(/your email will not be published/i)
      ).toBeInTheDocument()
    })

    it('shows error when submitting empty comment', async () => {
      const user = userEvent.setup()
      render(<CommentForm {...defaultProps} />)

      // Fill name and email but not comment
      await user.type(screen.getByPlaceholderText('Your name *'), 'Test User')
      await user.type(screen.getByPlaceholderText('Your email *'), 'test@example.com')

      // Submit - button should be disabled with empty content
      const submitButton = screen.getByRole('button', { name: /post comment/i })
      expect(submitButton).toBeDisabled()
    })

    it('shows error when name and email are missing', async () => {
      const user = userEvent.setup()
      render(<CommentForm {...defaultProps} />)

      // Type comment content
      await user.type(screen.getByPlaceholderText('Share your thoughts...'), 'Test comment')

      // Submit form
      const submitButton = screen.getByRole('button', { name: /post comment/i })
      await user.click(submitButton)

      expect(screen.getByText('Name and email are required')).toBeInTheDocument()
    })

    it('submits comment successfully', async () => {
      createComment.mockResolvedValue({
        success: true,
        message: 'Comment submitted successfully',
        comment: { id: '1', content: 'Test comment' },
        isPending: true,
      })

      const user = userEvent.setup()
      const onCommentAdded = jest.fn()
      render(<CommentForm {...defaultProps} onCommentAdded={onCommentAdded} />)

      await user.type(screen.getByPlaceholderText('Your name *'), 'Test User')
      await user.type(screen.getByPlaceholderText('Your email *'), 'test@example.com')
      await user.type(screen.getByPlaceholderText('Share your thoughts...'), 'Test comment')

      await user.click(screen.getByRole('button', { name: /post comment/i }))

      await waitFor(() => {
        expect(createComment).toHaveBeenCalledWith({
          articleId: '123',
          content: 'Test comment',
          parentId: null,
          guestName: 'Test User',
          guestEmail: 'test@example.com',
          website_url: '', // Honeypot field is empty string
        })
      })
    })

    it('contains honeypot field', () => {
      const { container } = render(<CommentForm {...defaultProps} />)

      const honeypotInput = container.querySelector('#website_url_main')
      expect(honeypotInput).toBeInTheDocument()
      expect(honeypotInput).toHaveAttribute('tabindex', '-1')
    })
  })

  describe('Logged in user mode', () => {
    const loggedInUser = {
      id: 'user-123',
      email: 'user@example.com',
      user_metadata: {
        full_name: 'John Doe',
        avatar_url: null,
      },
    }

    it('shows user info when logged in', () => {
      render(<CommentForm {...defaultProps} user={loggedInUser} />)

      expect(screen.getByText(/commenting as/i)).toBeInTheDocument()
      expect(screen.getByText('John Doe')).toBeInTheDocument()
    })

    it('does not show name/email fields when logged in', () => {
      render(<CommentForm {...defaultProps} user={loggedInUser} />)

      expect(screen.queryByPlaceholderText('Your name *')).not.toBeInTheDocument()
      expect(screen.queryByPlaceholderText('Your email *')).not.toBeInTheDocument()
    })

    it('does not show privacy note when logged in', () => {
      render(<CommentForm {...defaultProps} user={loggedInUser} />)

      expect(
        screen.queryByText(/your email will not be published/i)
      ).not.toBeInTheDocument()
    })
  })

  describe('Reply mode', () => {
    it('shows Post Reply button for replies', () => {
      render(<CommentForm {...defaultProps} parentId="parent-123" />)

      expect(screen.getByRole('button', { name: /post reply/i })).toBeInTheDocument()
    })

    it('shows reply placeholder', () => {
      render(<CommentForm {...defaultProps} parentId="parent-123" />)

      expect(screen.getByPlaceholderText('Write your reply...')).toBeInTheDocument()
    })

    it('shows cancel button when onCancel provided', () => {
      const onCancel = jest.fn()
      render(<CommentForm {...defaultProps} parentId="parent-123" onCancel={onCancel} />)

      expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument()
    })

    it('calls onCancel when cancel clicked', async () => {
      const user = userEvent.setup()
      const onCancel = jest.fn()
      render(<CommentForm {...defaultProps} parentId="parent-123" onCancel={onCancel} />)

      await user.click(screen.getByRole('button', { name: /cancel/i }))

      expect(onCancel).toHaveBeenCalled()
    })
  })

  describe('Persian locale', () => {
    it('shows Persian placeholder', () => {
      render(<CommentForm {...defaultProps} locale="fa" />)

      expect(screen.getByPlaceholderText('نظر خود را بنویسید...')).toBeInTheDocument()
    })

    it('shows Persian button text', () => {
      render(<CommentForm {...defaultProps} locale="fa" />)

      expect(screen.getByRole('button', { name: /ارسال نظر/i })).toBeInTheDocument()
    })

    it('shows Persian error messages', async () => {
      const user = userEvent.setup()
      render(<CommentForm {...defaultProps} locale="fa" />)

      await user.type(screen.getByPlaceholderText('نظر خود را بنویسید...'), 'تست')
      await user.click(screen.getByRole('button', { name: /ارسال نظر/i }))

      expect(screen.getByText('نام و ایمیل الزامی است')).toBeInTheDocument()
    })
  })

  describe('Error handling', () => {
    it('shows error from server', async () => {
      createComment.mockResolvedValue({
        error: 'Server error occurred',
      })

      const user = userEvent.setup()
      render(<CommentForm {...defaultProps} />)

      await user.type(screen.getByPlaceholderText('Your name *'), 'Test User')
      await user.type(screen.getByPlaceholderText('Your email *'), 'test@example.com')
      await user.type(screen.getByPlaceholderText('Share your thoughts...'), 'Test comment')

      await user.click(screen.getByRole('button', { name: /post comment/i }))

      await waitFor(() => {
        expect(screen.getByText('Server error occurred')).toBeInTheDocument()
      })
    })
  })
})

'use client'

import {
  Instagram,
  Linkedin,
  Mail,
  MapPin,
  Phone,
  Send,
  Twitter,
  Youtube,
} from "lucide-react";
import { TelegramIcon } from "./icons/TelegramIcon";
import { WhatsappIcon } from "./icons/WhatsappIcon";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import emailjs from '@emailjs/browser';

export const ContactSection = () => {
  const { t } = useTranslation();
  const { toast } = useToast();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // EmailJS configuration from environment variables
      const serviceId = import.meta.env.VITE_EMAILJS_SERVICE_ID;
      const templateId = import.meta.env.VITE_EMAILJS_TEMPLATE_ID;
      const publicKey = import.meta.env.VITE_EMAILJS_PUBLIC_KEY;

      if (!serviceId || !templateId || !publicKey) {
        throw new Error('EmailJS configuration missing. Please check your environment variables.');
      }

      await emailjs.sendForm(
        serviceId,
        templateId,
        e.target,
        publicKey
      );

      toast({
        title: t("contact.toast.success"),
        description: t("contact.toast.successDescription"),
      });
      
      // Reset form
      e.target.reset();
      
    } catch (error) {
      console.error('EmailJS error:', error);
      toast({
        title: t("contact.toast.error"),
        description: t("contact.toast.errorDescription"),
        variant: "destructive",
      });
    } finally {
      setIsSubmitting(false);
    }
  };
  return (
    <section id="contact" className="py-24 px-4 relative bg-secondary/30">
      <div className="container mx-auto max-w-5xl">
        <h2 className="text-3xl md:text-4xl font-bold mb-4 text-center">
          {t("contact.title")} <span className="text-primary">{t("contact.touch")}</span>
        </h2>

        <p className="text-center text-muted-foreground mb-12 max-w-2xl mx-auto">
          {t("contact.description")}
        </p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
          <div className="space-y-8">
            <h3 className="text-2xl font-semibold mb-6">
              {t("contact.contactInformation")}
            </h3>

            <div className="space-y-6 justify-center">
              <div className="flex items-start space-x-4">
                <div className="p-3 rounded-full bg-primary/10">
                  <Mail className="h-6 w-6 text-primary" />{" "}
                </div>
                <div>
                  <h4 className="font-medium">{t("contact.email")}</h4>
                  <a
                    href="mailto:sandmanshiri@gmail.com"
                    className="text-muted-foreground hover:text-primary transition-colors"
                  >
                    sandmanshiri@gmail.com
                  </a>
                </div>
              </div>
              <div className="flex items-start space-x-4">
                <div className="p-3 rounded-full bg-primary/10">
                  <Phone className="h-6 w-6 text-primary" />{" "}
                </div>
                <div>
                  <h4 className="font-medium">{t("contact.phone")}</h4>
                  <a
                    href="tel:+989209954805"
                    className="text-muted-foreground hover:text-primary transition-colors"
                  >
                    +98 920 995 4805
                  </a>
                </div>
              </div>
              <div className="flex items-start space-x-4">
                <div className="p-3 rounded-full bg-primary/10">
                  <MapPin className="h-6 w-6 text-primary" />{" "}
                </div>
                <div>
                  <h4 className="font-medium">{t("contact.location")}</h4>
                  <a className="text-muted-foreground hover:text-primary transition-colors">
                    {t("contact.locationValue")}
                  </a>
                </div>
              </div>
            </div>

            <div className="pt-8">
              <h4 className="font-medium mb-4">{t("contact.connectWithMe")}</h4>
              <div className="flex space-x-4 justify-center">
                <a href="https://www.linkedin.com/in/mohammadhasanshiri" target="_blank">
                  <Linkedin />
                </a>
                <a href="https://x.com/MHasanshiri" target="_blank">
                  <Twitter />
                </a>
                <a href="https://www.instagram.com/mhasanshiri/" target="_blank">
                  <Instagram />
                </a>
                <a href="https://t.me/@Mhasanshiri" target="_blank">
                  <TelegramIcon />
                </a>
                <a href="https://wa.me/989209954805" target="_blank">
                  <WhatsappIcon />
                </a>
                <a href="https://www.youtube.com/@sire_jeff" target="_blank">
                  <Youtube className="text-foreground hover:text-primary transition-colors" />
                </a>
              </div>
            </div>
          </div>

          <div className="bg-card p-8 rounded-lg shadow-xs">
            <h3 className="text-2xl font-semibold mb-6">{t("contact.sendMessage")}</h3>

            <form className="space-y-6" onSubmit={handleSubmit}>
              <div>
