'use client'

import { createContext, useContext, useEffect, useState } from 'react';
import { getRandomTheme } from './colors';

const ThemeContext = createContext({
  currentTheme: null,
  setTheme: () => {},
});

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

export const ThemeProvider = ({ children }) => {
  const [currentTheme, setCurrentTheme] = useState(null);

  // Function to apply a random theme
  const applyRandomTheme = () => {
    const theme = getRandomTheme();
    setTheme(theme);
  };

  // Apply theme on initial mount
  useEffect(() => {
    applyRandomTheme();
  }, []);

  // Handle refresh and visibility changes
  useEffect(() => {
    const handleRefresh = () => {
      if (document.visibilityState === 'visible') {
        applyRandomTheme();
      }
    };

    // Listen for page refresh
    window.addEventListener('load', handleRefresh);
    document.addEventListener('visibilitychange', handleRefresh);

    return () => {
      window.removeEventListener('load', handleRefresh);
      document.removeEventListener('visibilitychange', handleRefresh);
    };
  }, []);

  const setTheme = (theme) => {
    if (!theme) return;

    if (currentTheme) {
      document.documentElement.classList.remove(currentTheme.class);
    }
    document.documentElement.classList.add(theme.class);
    document.documentElement.style.setProperty('--primary-hue', theme.hue.toString());
    setCurrentTheme(theme);
  };

  return (
    <ThemeContext.Provider value={{ currentTheme, setTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

'use client'

import { Moon, Sun } from "lucide-react";
import { useEffect, useState } from "react";
import { cn } from "@/lib/utils";

export const ThemeToggle = () => {
  const [isDarkMode, setIsDarkMode] = useState(false);

  useEffect(() => {
    const storedTheme = localStorage.getItem("theme");
    if (storedTheme === "dark") {
      setIsDarkMode(true);
      document.documentElement.classList.add("dark");
    } else {
      localStorage.setItem("theme", "light");
      setIsDarkMode(false);
    }
  }, []);

  const toggleTheme = () => {
    if (isDarkMode) {
      document.documentElement.classList.remove("dark");
      localStorage.setItem("theme", "light");
      setIsDarkMode(false);
    } else {
      document.documentElement.classList.add("dark");
      localStorage.setItem("theme", "dark");
      setIsDarkMode(true);
    }
  };

  return (
    <button
      onClick={toggleTheme}
      className={cn(
        "flex items-center gap-2 px-3 py-2 rounded-lg transition-colors duration-300",
        "bg-secondary/70 hover:bg-secondary text-foreground",
        "border border-border hover:border-primary/50",
        "focus:outline-none focus:ring-2 focus:ring-primary/50"
      )}
      title={isDarkMode ? 'Switch to Light Mode' : 'Switch to Dark Mode'}
    >
      {isDarkMode ? (
        <Sun size={18} className="text-yellow-400" />
      ) : (
        <Moon size={18} className="text-blue-400" />
      )}
    </button>
  );
};

