            title="Add Link"
          >
            <LinkIcon className="w-4 h-4" />
          </ToolbarButton>
          <ToolbarButton onClick={addImage} title="Add Image">
            <ImageIcon className="w-4 h-4" />
          </ToolbarButton>
          <ToolbarButton
            onClick={() => setShowYoutubeModal(true)}
            title="Add YouTube Video"
          >
            <YoutubeIcon className="w-4 h-4" />
          </ToolbarButton>
        </ToolbarGroup>

        <ToolbarDivider />

        {/* Undo/Redo */}
        <ToolbarGroup>
          <ToolbarButton
            onClick={() => editor.chain().focus().undo().run()}
            disabled={!editor.can().undo()}
            title="Undo"
          >
            <Undo className="w-4 h-4" />
          </ToolbarButton>
          <ToolbarButton
            onClick={() => editor.chain().focus().redo().run()}
            disabled={!editor.can().redo()}
            title="Redo"
          >
            <Redo className="w-4 h-4" />
          </ToolbarButton>
        </ToolbarGroup>
      </div>

      {/* Editor Content */}
      <EditorContent editor={editor} />

      {/* Link Modal */}
      {showLinkModal && (
        <Modal onClose={() => setShowLinkModal(false)}>
          <h3 className="text-lg font-semibold mb-4">Add Link</h3>
          <input
            type="url"
            value={linkUrl}
            onChange={(e) => setLinkUrl(e.target.value)}
            placeholder="https://example.com"
            className="w-full px-3 py-2 border border-border rounded-lg bg-background text-foreground mb-4"
            autoFocus
          />
          <div className="flex gap-2 justify-end">
            <button
              onClick={() => setShowLinkModal(false)}
              className="px-4 py-2 text-sm text-muted-foreground hover:text-foreground"
            >
              Cancel
            </button>
            <button
              onClick={setLink}
              className="px-4 py-2 text-sm bg-primary text-primary-foreground rounded-lg"
            >
              Add Link
            </button>
          </div>
        </Modal>
      )}

      {/* YouTube Modal */}
      {showYoutubeModal && (
        <Modal onClose={() => setShowYoutubeModal(false)}>
          <h3 className="text-lg font-semibold mb-4">Add YouTube Video</h3>
          <input
            type="url"
            value={youtubeUrl}
            onChange={(e) => setYoutubeUrl(e.target.value)}
            placeholder="https://www.youtube.com/watch?v=..."
            className="w-full px-3 py-2 border border-border rounded-lg bg-background text-foreground mb-4"
            autoFocus
          />
          <div className="flex gap-2 justify-end">
            <button
              onClick={() => setShowYoutubeModal(false)}
              className="px-4 py-2 text-sm text-muted-foreground hover:text-foreground"
            >
              Cancel
            </button>
            <button
              onClick={addYoutube}
              className="px-4 py-2 text-sm bg-primary text-primary-foreground rounded-lg"
            >
              Add Video
            </button>
          </div>
        </Modal>
      )}
    </div>
  )
}

// Helper Components
function ToolbarGroup({ children }) {
  return <div className="flex gap-0.5">{children}</div>
}

function ToolbarDivider() {
  return <div className="w-px bg-border mx-1" />
}

function ToolbarButton({ onClick, isActive, disabled, title, children }) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      title={title}
      className={`p-2 rounded transition-colors ${
        isActive
          ? 'bg-primary text-primary-foreground'
          : 'text-muted-foreground hover:text-foreground hover:bg-secondary'
      } ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
    >
      {children}
    </button>
  )
}

function Modal({ onClose, children }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div
        className="absolute inset-0 bg-black/50"
        onClick={onClose}
      />
      <div className="relative bg-card border border-border rounded-xl p-6 w-full max-w-md mx-4 shadow-xl">
        {children}
      </div>
    </div>
  )
}

