/**
 * Generate unique slug from title
 */
export async function generateSlug(title) {
  const supabase = await createClient()

  // Create base slug
  let slug = title
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim()

  // Check if exists
  const { data: existing } = await supabase
    .from('articles')
    .select('slug')
    .like('slug', `${slug}%`)

  if (existing?.length) {
    const slugs = existing.map(a => a.slug)
    let counter = 1
    let newSlug = slug
    while (slugs.includes(newSlug)) {
      newSlug = `${slug}-${counter}`
      counter++
    }
    slug = newSlug
  }

  return slug
}

/**
 * Publish scheduled articles
 * Called by cron job to publish articles whose published_at date has arrived
 */
export async function publishScheduledArticles() {
  const supabase = await createClient()
  const now = new Date().toISOString()

  // Get all draft articles scheduled to be published
  const { data: articles } = await supabase
    .from('articles')
    .select('id')
    .eq('status', 'draft')
    .lte('published_at', now)

  if (!articles?.length) {
    return { count: 0 }
  }

  // Publish them
  const { data } = await supabase
    .from('articles')
    .update({ status: 'published' })
    .in('id', articles.map(a => a.id))
    .select()

  // Revalidate paths
  revalidatePath('/en/blog')
  revalidatePath('/fa/blog')

  return { count: data?.length || 0 }
}

