  { slug: 'libertad', color: '#3b82f6', title: 'Libertad' },
  { slug: 'interpolation', color: '#10b981', title: 'Interpolation' },
  { slug: 'restaurant-analysis', color: '#f59e0b', title: 'Restaurant Analysis' },
