export const metadata = {
  title: 'Admin Dashboard',
  default: 'Admin | %s | Admin',
  template: '%s | Admin',
}

export default async function AdminLayout({ children }) {
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()

  if (!user) {
    redirect('/auth/login?redirectTo=/admin')
  }

  // Get user profile to check admin role
  const { data: profile } = await supabase
    .from('profiles')
    .select('*')
    .eq('id', user.id)
    .maybeSingle()

  // You can add role checking here if needed

  return (
    <div className="min-h-screen bg-background">
      <AIProvider>
        <AdminSidebar user={user} profile={profile} />
        <FloatingAIAssistant />
        <div className="lg:pl-64">
          <main className="p-6">{children}</main>
        </div>
      </AIProvider>
    </div>
  )
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse } from 'next/server'

export async function updateSession(request) {
  let supabaseResponse = NextResponse.next({
    request,
  })

  let url = process.env.NEXT_PUBLIC_SUPABASE_URL
  let key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

  if (!url || !key) {
    // If Supabase is not configured, skip session update
    return supabaseResponse
  }

  // Trim whitespace and remove any newlines
  url = url.trim().replace(/[\r\n]/g, '')
  key = key.trim().replace(/[\r\n]/g, '')

  const supabase = createServerClient(
    url,
    key,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) =>
            request.cookies.set(name, value)
          )
          supabaseResponse = NextResponse.next({
            request,
          })
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options)
          )
        },
      },
    }
  )

  // IMPORTANT: Avoid writing any logic between createServerClient and
  // supabase.auth.getUser(). A simple mistake could make it very hard to debug
  // issues with users being randomly logged out.

  const {
    data: { user },
  } = await supabase.auth.getUser()

  // Protect admin routes
  if (request.nextUrl.pathname.startsWith('/admin')) {
    if (!user) {
      // Redirect to login if not authenticated
      const url = request.nextUrl.clone()
      url.pathname = '/auth/login'
      url.searchParams.set('redirectTo', request.nextUrl.pathname)
      return NextResponse.redirect(url)
    }

    // Check if user is admin (you can add role check here)
    // For now, any authenticated user with specific email can access admin
    const adminEmails = process.env.ADMIN_EMAILS?.split(',') || []
    if (adminEmails.length > 0 && !adminEmails.includes(user.email)) {
      // Not an admin, redirect to home
      const url = request.nextUrl.clone()
      url.pathname = '/'
      return NextResponse.redirect(url)
    }
  }

  // IMPORTANT: You *must* return the supabaseResponse object as it is.
  return supabaseResponse
}

