/**
 * Get site settings (key-value pattern)
 * Returns settings grouped by category
 * Note: Does NOT include a get() method because functions cannot be serialized
 * when passed from Server Actions to Client Components.
 * Use getSettingValue() helper in client components instead.
 */
export async function getSiteSettings() {
  const supabase = await createClient()

  const { data: settings, error } = await supabase
    .from('site_settings')
    .select('*')

  if (error) {
    console.error('Error fetching site settings:', error)
    return { settings: { byKey: {}, byCategory: {}, all: [] } }
  }

  // Convert to object with grouped access
  const grouped = {
    all: settings || [],
    byKey: {},
    byCategory: { contact: {}, social: {}, github: {}, external: {}, general: {} }
  }

  for (const setting of settings || []) {
    // Add to byKey map
    grouped.byKey[setting.key] = setting

    // Add to category
    if (setting.category) {
      grouped.byCategory[setting.category] = grouped.byCategory[setting.category] || {}
      grouped.byCategory[setting.category][setting.key] = setting

      // For convenience, add direct value access
      const valueKey = setting.key.replace(`${setting.category}_`, '')
      if (valueKey !== setting.key) {
        grouped.byCategory[setting.category][valueKey] = setting.value_en
      }
    }
  }

  return { settings: grouped }
}

/**
 * Internal helper to get a setting value from the settings object
 * Used by server-side helper functions
 */
function _getValue(settings, key, defaultValue = null, locale = 'en') {
  const setting = settings?.byKey?.[key]
  if (!setting) return defaultValue
  return locale === 'fa' ? (setting.value_fa || setting.value_en) : setting.value_en
}

/**
 * Update a single site setting
 */
export async function updateSiteSetting(key, valueEn, valueFa = null, type = null) {
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) {
    return { error: 'Not authenticated' }
  }

  const updateData = {
    value_en: valueEn,
    updated_at: new Date().toISOString()
  }

  if (valueFa !== null) {
    updateData.value_fa = valueFa
  }

  if (type !== null) {
    updateData.type = type
  }

  const { data, error } = await supabase
    .from('site_settings')
    .update(updateData)
    .eq('key', key)
    .select()
    .single()

  if (error) {
    console.error('Error updating site setting:', error)
    return { error: error.message }
  }

  revalidatePath('/')
  revalidatePath('/en')
  revalidatePath('/fa')
  revalidatePath('/admin/settings')

  return { setting: data }
}

/**
 * Update multiple site settings
 * @param {Array} settings - Array of { key, value_en, value_fa, type } objects
 */
export async function updateSiteSettings(settings) {
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) {
    return { error: 'Not authenticated' }
  }

  // Handle empty array
  if (!settings || settings.length === 0) {
    return { success: true }
  }

  // Update each setting - expects array of { key, value_en, value_fa, type } objects
  for (const setting of settings) {
    const { key, value_en, value_fa, type } = setting

    const updateData = {
      value_en,
      updated_at: new Date().toISOString(),
    }

    // Only include value_fa if provided
    if (value_fa !== undefined && value_fa !== null) {
      updateData.value_fa = value_fa
    }

    // Only include type if provided
    if (type !== undefined && type !== null) {
      updateData.type = type
    }

    const { error } = await supabase
      .from('site_settings')
      .update(updateData)
      .eq('key', key)

    if (error) {
      console.error(`Error updating setting ${key}:`, error)
      // Continue with other settings even if one fails
    }
  }

  revalidatePath('/')
  revalidatePath('/en')
  revalidatePath('/fa')
  revalidatePath('/admin/settings')

  return { success: true }
}

