'use server'

import { createClient as createRegularClient, createAdminClient } from '@/lib/supabase/server'

/**
 * Upload image to Supabase Storage
 * Uses admin client (service role) to bypass RLS for server-side uploads
 * Verifies user is authenticated admin before allowing upload
 */
export async function uploadImage(formData) {
  // First, verify the user is an authenticated admin
  const userSupabase = await createRegularClient()
  const { data: { user }, error: userError } = await userSupabase.auth.getUser()

  if (userError || !user) {
    return { error: 'Authentication required' }
  }

  // Check if user has admin role
  const { data: profile } = await userSupabase
    .from('profiles')
    .select('role')
    .eq('id', user.id)
    .single()

  if (!profile || profile.role !== 'admin') {
    return { error: 'Admin access required' }
  }

  // Use admin client for the actual upload (bypasses RLS)
  const supabase = await createAdminClient()

  const file = formData.get('file')
  const bucket = formData.get('bucket') || 'articles'
  const folder = formData.get('folder') || ''

  if (!file) {
    return { error: 'No file provided' }
  }

  // Generate unique filename
  const fileExt = file.name.split('.').pop()
  const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`
  const filePath = folder ? `${folder}/${fileName}` : fileName

  const { data, error } = await supabase.storage
    .from(bucket)
    .upload(filePath, file, {
      cacheControl: '3600',
      upsert: false,
    })

  if (error) {
    console.error('Error uploading image:', error)
    return { error: error.message }
  }

  // Get public URL
  const { data: urlData } = supabase.storage
    .from(bucket)
    .getPublicUrl(data.path)

  return {
    path: data.path,
    url: urlData.publicUrl,
  }
}

/**
 * Delete image from Supabase Storage
 * Uses admin client (service role) to bypass RLS for server-side deletions
 * Verifies user is authenticated admin before allowing deletion
 */
export async function deleteImage(path, bucket = 'articles') {
  // Verify the user is an authenticated admin
  const userSupabase = await createRegularClient()
  const { data: { user }, error: userError } = await userSupabase.auth.getUser()

  if (userError || !user) {
    return { error: 'Authentication required' }
  }

  // Check if user has admin role
  const { data: profile } = await userSupabase
    .from('profiles')
    .select('role')
    .eq('id', user.id)
    .single()

  if (!profile || profile.role !== 'admin') {
    return { error: 'Admin access required' }
  }

  // Use admin client for the actual deletion
  const supabase = await createAdminClient()

  const { error } = await supabase.storage
    .from(bucket)
    .remove([path])

  if (error) {
    console.error('Error deleting image:', error)
    return { error: error.message }
  }

  return { success: true }
}

/**
 * List images in a bucket/folder
 * Uses admin client (service role) to bypass RLS for server-side listing
 */
export async function listImages(bucket = 'articles', folder = '') {
  const supabase = await createAdminClient()

  const { data, error } = await supabase.storage
    .from(bucket)
    .list(folder, {
      limit: 100,
      offset: 0,
      sortBy: { column: 'created_at', order: 'desc' },
    })

  if (error) {
    console.error('Error listing images:', error)
    return { images: [], error: error.message }
  }

  // Filter out folders and get public URLs
  const images = (data || [])
    .filter(item => item.id) // Filter out folders
    .map(item => {
      const path = folder ? `${folder}/${item.name}` : item.name
      const { data: urlData } = supabase.storage
        .from(bucket)
        .getPublicUrl(path)

      return {
        id: item.id,
        name: item.name,
        path,
        url: urlData.publicUrl,
        created_at: item.created_at,
        size: item.metadata?.size,
      }
    })

  return { images }
}

/**
 * Get storage URL for a path
 * Uses admin client (service role) for consistency
 */
export async function getStorageUrl(path, bucket = 'articles') {
  const supabase = await createAdminClient()

  const { data } = supabase.storage
    .from(bucket)
    .getPublicUrl(path)

  return data.publicUrl
}

/**
 * Streaming Utilities for Server-Sent Events (SSE) APIs
 * Provides reusable SSE parsing for OpenRouter, OpenAI, Anthropic, etc.
 */

/**
 * Custom error for streaming failures
 */
export class StreamError extends Error {
  constructor(message, { cause, code, context } = {}) {
    super(message);
    this.name = 'StreamError';
    this.cause = cause;
    this.code = code;
    this.context = context;
  }
}

/**
 * Parse SSE chunks from a ReadableStream
 * @param {ReadableStream} stream - The response body stream
 * @param {Object} options - Parser options
 * @returns {AsyncGenerator<string>} Yields parsed JSON objects
 */
export async function* parseSSEChunks(stream, options = {}) {
  const {
    onChunk = null,
    onError = null,
    maxBufferSize = 1024 * 1024, // 1MB max buffer
  } = options;

  const reader = stream.getReader();
  const decoder = new TextDecoder('utf-8');
  let buffer = '';
  let bufferLength = 0;

  try {
    while (true) {
      const { done, value } = await reader.read();

      if (done) {
        // Process any remaining data in buffer
        if (buffer.trim()) {
          yield* processBuffer(buffer);
        }
        break;
      }

      // Decode chunk and add to buffer
      const chunk = decoder.decode(value, { stream: true });
      buffer += chunk;
      bufferLength += chunk.length;

      // Safety check for buffer overflow
      if (bufferLength > maxBufferSize) {
        throw new StreamError('Buffer overflow - chunk too large', {
          code: 'BUFFER_OVERFLOW',
          context: { bufferSize: bufferLength }
        });
      }

      // Call onChunk callback if provided
      if (onChunk) {
        onChunk(chunk);
      }

      // Process complete lines from buffer
      const lines = buffer.split(/\r?\n/);
      buffer = lines.pop() || ''; // Keep incomplete line in buffer

      for (const line of lines) {
        if (line.trim()) {
          yield* processLine(line);
        }
      }
    }
  } catch (error) {
    if (onError) {
      onError(error);
    }
    throw new StreamError('Failed to parse stream', {
      cause: error,
      code: 'PARSE_ERROR'
    });
  } finally {
    reader.releaseLock();
  }

  // Helper to process SSE lines
  function* processLine(line) {
    // SSE format: "data: {...}"
    if (line.startsWith('data: ')) {
      const data = line.slice(6); // Remove "data: " prefix

      // Handle [DONE] signal
      if (data === '[DONE]') {
        return;
      }

      try {
        const parsed = JSON.parse(data);
        yield parsed;
      } catch (error) {
        throw new StreamError('Failed to parse SSE data', {
          cause: error,
          code: 'JSON_PARSE_ERROR',
          context: { data }
        });
      }
    }
  }

  // Helper to process remaining buffer
  function* processBuffer(remaining) {
    const lines = remaining.split(/\r?\n/);
    for (const line of lines) {
      if (line.trim()) {
        yield* processLine(line);
      }
    }
  }
}

/**
 * Create a configured SSE parser for specific API formats
 * @param {string} format - 'openrouter' | 'openai' | 'anthropic'
 * @returns {Function} Parser function
 */
export function createSSEParser(format) {
  const parsers = {
    openrouter: (stream, options) => parseSSEChunks(stream, {
      ...options,
      transform: (data) => {
        // OpenRouter specific: extract delta from choices[0].delta
        if (data.choices?.[0]?.delta) {
          return data.choices[0].delta;
        }
        return data;
      }
    }),

    openai: (stream, options) => parseSSEChunks(stream, {
      ...options,
      transform: (data) => {
        // OpenAI format
        if (data.choices?.[0]?.delta) {
          return data.choices[0].delta;
        }
        return data;
      }
    }),

    anthropic: (stream, options) => parseSSEChunks(stream, {
      ...options,
      transform: (data) => {
        // Anthropic format
        if (data.delta) {
          return data.delta;
        }
        return data;
      }
    })
  };

  return parsers[format] || parsers.openrouter;
}

/**
 * Validate SSE format string
 * @param {string} sseString - SSE string to validate
 * @returns {boolean} True if valid SSE format
 */
export function validateSSEFormat(sseString) {
  if (typeof sseString !== 'string') return false;

  const lines = sseString.split(/\r?\n/);
  let hasData = false;

  for (const line of lines) {
    if (line.startsWith('data: ')) {
      hasData = true;

      // Try to parse JSON
      const data = line.slice(6);
      try {
        JSON.parse(data);
      } catch {
        return false; // Invalid JSON
      }
    }
  }

  return hasData;
}

