// Cache strategies
const strategies = {
  // Cache first, fall back to network
  cacheFirst: async (request) => {
    const cache = await caches.open(CACHE_NAME)
    const cached = await cache.match(request)

    if (cached) {
      // Update cache in background
      fetch(request).then((response) => {
        if (response.ok) {
          cache.put(request, response.clone())
        }
      })
      return cached
    }

    const response = await fetch(request)
    if (response.ok) {
      cache.put(request, response.clone())
    }
    return response
  },

  // Network first, fall back to cache
  networkFirst: async (request) => {
    const cache = await caches.open(CACHE_NAME)

    try {
      const response = await fetch(request)
      if (response.ok) {
        cache.put(request, response.clone())
      }
      return response
    } catch (error) {
      const cached = await cache.match(request)
      if (cached) {
        return cached
      }
      throw error
    }
  },

  // Stale while revalidate
  staleWhileRevalidate: async (request) => {
    const cache = await caches.open(CACHE_NAME)
    const cached = await cache.match(request)

    // Fetch in background
    const fetchPromise = fetch(request).then((response) => {
      if (response.ok) {
        cache.put(request, response.clone())
      }
      return response
    })

    // Return cached version immediately or wait for fetch
    return cached || fetchPromise
  },
}

// Determine which strategy to use based on request
function getStrategy(request) {
  const url = new URL(request.url)

  // Skip non-GET requests
  if (request.method !== 'GET') return null

  // Skip chrome extensions and other protocols
  if (!url.protocol.startsWith('http')) return null

  // Images - cache first
  if (CACHE_PATTERNS.images.test(url.pathname)) {
    return strategies.cacheFirst
  }

  // Fonts - cache first
  if (CACHE_PATTERNS.fonts.test(url.pathname)) {
    return strategies.cacheFirst
  }

  // API calls - network first
  if (CACHE_PATTERNS.api.test(url.pathname)) {
    return strategies.networkFirst
  }

  // Static assets from same origin - stale while revalidate
  if (url.origin === location.origin) {
    return strategies.staleWhileRevalidate
  }

  return null
}

// Install event - cache static assets
self.addEventListener('install', (event) => {
  console.log('[SW] Installing service worker...')

  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        console.log('[SW] Caching static assets:', STATIC_ASSETS)
        return cache.addAll(STATIC_ASSETS)
      })
      .then(() => self.skipWaiting())
      .catch((error) => {
        console.error('[SW] Failed to cache static assets:', error)
        // Still activate the service worker even if caching fails
        return self.skipWaiting()
      })
  )
})

// Activate event - clean up old caches
self.addEventListener('activate', (event) => {
  console.log('[SW] Activating service worker...')

  event.waitUntil(
    caches.keys()
      .then((cacheNames) => {
        return Promise.all(
          cacheNames
            .filter((cacheName) => cacheName.startsWith('portfolio-') && cacheName !== CACHE_NAME)
            .map((cacheName) => {
              console.log('[SW] Deleting old cache:', cacheName)
              return caches.delete(cacheName)
            })
        )
      })
      .then(() => self.clients.claim())
  )
})

// Fetch event - handle requests with appropriate strategy
self.addEventListener('fetch', (event) => {
  const strategy = getStrategy(event.request)

  if (strategy) {
    event.respondWith(strategy(event.request))
  }
})

// Message event - handle messages from clients
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting()
  }

  if (event.data && event.data.type === 'CLEAR_CACHE') {
    caches.delete(CACHE_NAME).then(() => {
      event.ports[0].postMessage({ success: true })
    })
  }
})

'use server'

import { createClient } from '@/lib/supabase/server'
import { revalidatePath } from 'next/cache'

/**
 * Get all tags
 */
export async function getTags() {
  const supabase = await createClient()

  const { data: tags, error } = await supabase
    .from('tags')
    .select('*')
    .order('name_en', { ascending: true })

  if (error) {
    console.error('Error fetching tags:', error)
    return []
  }

  return tags || []
}

/**
 * Get tags with article count
 */
export async function getTagsWithCount() {
  const supabase = await createClient()

  const { data: tags, error } = await supabase
    .from('tags')
    .select(`
      *,
      article_tags:article_tags(count)
    `)
    .order('name_en', { ascending: true })

  if (error) {
    console.error('Error fetching tags with count:', error)
    return []
  }

  return tags?.map(tag => ({
    ...tag,
    article_count: tag.article_tags?.[0]?.count || 0,
    article_tags: undefined,
  })) || []
}

/**
 * Get popular tags (by article count)
 */
export async function getPopularTags(limit = 10) {
  const supabase = await createClient()

  const { data: tags, error } = await supabase
    .from('tags')
    .select(`
      *,
      article_tags:article_tags(count)
    `)
    .order('name_en', { ascending: true })
    .limit(50) // Get more to filter

  if (error) {
    console.error('Error fetching popular tags:', error)
    return []
  }

  // Sort by count and take top N
  return (tags || [])
    .map(tag => ({
      ...tag,
      article_count: tag.article_tags?.[0]?.count || 0,
      article_tags: undefined,
    }))
    .sort((a, b) => b.article_count - a.article_count)
    .slice(0, limit)
}

/**
 * Get single tag by slug
 */
export async function getTagBySlug(slug) {
  const supabase = await createClient()

  const { data: tag, error } = await supabase
    .from('tags')
    .select('*')
    .eq('slug', slug)
    .single()

  if (error) {
    console.error('Error fetching tag:', error)
    return null
  }

  return tag
}

/**
 * Create a new tag (admin only)
 */
export async function createTag(formData) {
  const supabase = await createClient()

  // Generate slug from English name
  const slug = formData.name_en
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim()

  const { data: tag, error } = await supabase
    .from('tags')
    .insert({ ...formData, slug })
    .select()
    .single()

  if (error) {
    console.error('Error creating tag:', error)
    return { error: error.message }
  }

  revalidatePath('/blog')
  revalidatePath('/admin/tags')

  return { tag }
}

/**
 * Update a tag (admin only)
 */
export async function updateTag(id, formData) {
  const supabase = await createClient()

  const { data: tag, error } = await supabase
    .from('tags')
    .update(formData)
    .eq('id', id)
    .select()
    .single()

  if (error) {
    console.error('Error updating tag:', error)
    return { error: error.message }
  }

  revalidatePath('/blog')
  revalidatePath('/admin/tags')

  return { tag }
}

/**
 * Delete a tag (admin only)
 */
export async function deleteTag(id) {
  const supabase = await createClient()

  const { error } = await supabase
    .from('tags')
    .delete()
    .eq('id', id)

  if (error) {
    console.error('Error deleting tag:', error)
    return { error: error.message }
  }

  revalidatePath('/blog')
  revalidatePath('/admin/tags')

  return { success: true }
}

/**
 * Create or get tag by name (for quick tag creation in editor)
 */
export async function getOrCreateTag(name_en, name_fa = '') {
  const supabase = await createClient()

  const slug = name_en
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim()

  // Check if exists
  const { data: existing } = await supabase
    .from('tags')
    .select('*')
    .eq('slug', slug)
    .single()

  if (existing) {
    return { tag: existing }
  }

  // Create new
  const { data: tag, error } = await supabase
    .from('tags')
    .insert({
      slug,
      name_en,
      name_fa: name_fa || name_en,
    })
    .select()
    .single()

  if (error) {
    console.error('Error creating tag:', error)
    return { error: error.message }
  }

  return { tag }
}

