function customRender(ui, options = {}) {
  const { locale = 'en', ...renderOptions } = options

  function Wrapper({ children }) {
    return (
      <div dir={locale === 'fa' ? 'rtl' : 'ltr'} lang={locale}>
        {children}
      </div>
    )
  }

  return render(ui, { wrapper: Wrapper, ...renderOptions })
}

